package caveman

import (
	"regexp"
	"strings"
)

// Preamble patterns commonly generated by LLMs (English & Portuguese)
var preamblePatterns = []*regexp.Regexp{
	regexp.MustCompile(`(?i)^(com certeza|certamente|claro|sem problemas|perfeito)[!.,\s]+(aqui está|vamos|vou|abaixo)[^\n]*\n+`),
	regexp.MustCompile(`(?i)^(sure|certainly|of course|absolutely)[!.,\s]+(here is|i have|let me|below)[^\n]*\n+`),
	regexp.MustCompile(`(?i)^(desculpe|peço desculpas|perdão|sinto muito)[!.,\s]+(pelo equívoco|pela confusão|pelo erro)[^\n]*\n+`),
	regexp.MustCompile(`(?i)^(i apologize|sorry for the confusion|my apologies)[!.,\s]+[^\n]*\n+`),
	regexp.MustCompile(`(?i)^here is the (code|solution|function|updated implementation)[^:\n]*:\s*\n+`),
	regexp.MustCompile(`(?i)^aqui está o (código|arquivo|script|exemplo)[^:\n]*:\s*\n+`),
}

var epiloguePatterns = []*regexp.Regexp{
	regexp.MustCompile(`(?i)\n+(espero que isso ajude|se precisar de algo mais|qualquer dúvida estou à disposição|avise se precisar)[^\n]*$`),
	regexp.MustCompile(`(?i)\n+(hope this helps|let me know if you have any questions|feel free to ask)[^\n]*$`),
}

// StripProlixity removes polite filler, preambles, and conversational fluff from the response.
func StripProlixity(response string) string {
	trimmed := strings.TrimSpace(response)

	// Strip preambles
	for _, re := range preamblePatterns {
		trimmed = re.ReplaceAllString(trimmed, "")
		trimmed = strings.TrimSpace(trimmed)
	}

	// Strip epilogues
	for _, re := range epiloguePatterns {
		trimmed = re.ReplaceAllString(trimmed, "")
		trimmed = strings.TrimSpace(trimmed)
	}

	return trimmed
}

// SystemDirective returns a concise prompt constraint to enforce direct answers from the model.
func SystemDirective() string {
	return "Be extremely concise. No conversational filler, preambles ('Sure thing', 'Here is'), apologies, or pleasantries. Output code, file paths, commands, and direct answers only."
}
